import tippy from "tippy.js";
import "tippy.js/dist/tippy.css";

(function () {
  var lastMouseOverElement = null;
  document.addEventListener("mouseover", function (event) {
    var element = event.target;

    if (element instanceof Element && element !== lastMouseOverElement) {
      lastMouseOverElement = element;
      var style = window.getComputedStyle(element);
      var whiteSpace = style.getPropertyValue("white-space");
      var textOverflow = style.getPropertyValue("text-overflow");
      var id = "tippyEllipsizedEl";

      var inner = function inner(content, el) {
        document.querySelectorAll("." + id).forEach(function (elem) {
          elem.classList.remove(id);
        });
        el.classList.add(id);
        tippy("." + id, {
          content: content
        });

        if (content === el.getAttribute("title")) {
          el.removeAttribute("title");
        }
      };

      var levels = 6;
      var dataTip;
      var el = element;

      for (var index = 0; index < levels; index++) {
        if (!el) continue;
        dataTip = el.getAttribute("data-tip");
        if (dataTip) continue;
        el = element.parentElement;
      }

      if (dataTip) {
        inner(dataTip, el);
      } else if (whiteSpace === "nowrap" && textOverflow === "ellipsis" && element.offsetWidth < element.scrollWidth) {
        inner(element.textContent, element);
      }
    }
  });
})();